import {
  GridEngineHeadless,
  Tilemap,
  GridEngineConfigHeadless,
  CharacterDataHeadless,
} from "grid-engine";
import PhaserRaycaster from "phaser-raycaster";

import { gameConfig, tileNames } from "game/config";

import {
  Box,
  CharacterName,
  CharactersState,
  LoaderResources,
  SceneConfig,
} from "type";
import { Monster, NPC, Player, Character } from "../Character";
import { playerManager } from "managers/PlayerManager";
import { between, getRandomArrayElements } from "utils";
import { playerConfig } from "managers/config";
import { lockedRandomItems, simpleRandomItems } from "items";
import { Pointer } from "./modules";
import { Light } from "../Light";
import { Flame } from "../Flame";
import { Raycaster } from "../Raycaster";

export class GameScene extends Phaser.Scene {
  gridEngine!: GridEngineHeadless;
  raycasterPlugin!: PhaserRaycaster;

  constructor(
    loaderResources: LoaderResources,
    currentMapPath: string,
    config: SceneConfig,
  ) {
    super();

    const { boxes = [] } = config || {};

    this.boxes.prepared = boxes;
    this.sceneConfig = config;
    this.loaderResources = loaderResources;
    this.currentMapJson = currentMapPath;
  }

  private sceneConfig: SceneConfig;
  cellSize = 0;

  cursors?: Phaser.Types.Input.Keyboard.CursorKeys;
  tilemap?: Phaser.Tilemaps.Tilemap;

  characters: CharactersState = {
    NPC: {},
    enemy: {},
  } as CharactersState;
  camera?: Phaser.Cameras.Scene2D.Camera;
  /**coordinates as "x|y" */
  boxes: {
    prepared: Box[];
    state: Record<string, Box>;
  } = { prepared: [], state: {} };

  private loaderResources: LoaderResources;
  private currentMapJson: string;
  private lightElements?: {
    state: Record<string, Light>;
    list: Light[];
  };

  preload() {
    Object.keys(this.loaderResources).forEach((key) => {
      const method = key as keyof LoaderResources;
      const values = this.loaderResources[method];
      values?.forEach((data) => {
        const callBack = (this.load[method] as Function).bind(this.load);
        callBack(...data);
      });
    });

    this.load.tilemapTiledJSON(gameConfig.names.map, this.currentMapJson);
    Object.keys(gameConfig.tiles).forEach((tileID) => {
      const path = gameConfig.tiles[tileID as keyof typeof gameConfig.tiles];
      this.load.image(tileID, path);
    });
  }

  private createCharacters(tilemap: Phaser.Tilemaps.Tilemap) {
    const { characters } = this.sceneConfig;
    const {
      player: playerConfig,
      NPC: npcConfig,
      enemy: enemyConfig,
    } = characters;

    const player = new Player(this, playerConfig);
    this.characters.player = player;

    this.camera = this.cameras.main;

    this.camera.setZoom(1.5); // в теорії це дозволяє додати можливість змінювати зум
    this.camera.setBounds(0, 0, tilemap.widthInPixels, tilemap.heightInPixels);
    this.camera.startFollow(player.sprite, true);

    const npc = Object.values(npcConfig).reduce((list, config) => {
      const { id } = config;
      list[id] = new NPC(this, config);
      return list;
    }, {} as Partial<Record<CharacterName, NPC>>);

    const monsters = Object.values(enemyConfig).reduce((list, config) => {
      const { id } = config;
      list[id] = new Monster(this, config);
      return list;
    }, {} as Partial<Record<CharacterName, Monster>>);

    return {
      player,
      npc,
      monsters,
    };
  }

  private createBoxes(layers: Phaser.Tilemaps.TilemapLayer[]) {
    let boxIndex = 0;

    layers.forEach((layer) => {
      layer.layer.data.forEach((line, i) => {
        line.forEach((tile) => {
          if (tile.properties.box) {
            const currentBox = this.boxes.prepared[boxIndex];
            const id = `${tile.x}|${tile.y}`;
            if (currentBox) {
              this.boxes.state[id] = currentBox;
            } else {
              // The box is not defined. It must be filled with random items
              const isLock = !(
                between(0, 100) <= gameConfig.gamePlay.randomBoxLockChance
              );

              const lock = isLock
                ? 0
                : between(0, playerConfig.skillsMaximumLevel.lockBreaking);

              const itemsAmount = between(
                1,
                gameConfig.gamePlay.randomItemsMaxAmount,
              );

              this.boxes.state[id] = {
                lock,
                items: getRandomArrayElements(
                  lock ? lockedRandomItems : simpleRandomItems,
                  itemsAmount,
                ),
              };
            }

            boxIndex++;
          }
        });
      });
    });
  }

  create() {
    const { characters } = this.sceneConfig;
    const { player: playerConfig } = characters;


    this.tilemap = this.make.tilemap({
      key: gameConfig.names.map,
    });

    this.cellSize = this.tilemap.tileWidth;
    const layers: Phaser.Tilemaps.TilemapLayer[] = [];

    this.tilemap.tilesets.forEach((tile) => {
      this.tilemap?.addTilesetImage(tile.name, tile.name);
    });

    for (let i = 0; i < (this.tilemap?.layers.length || 0); i++) {
      const layer = this.tilemap?.createLayer(
        i,
        this.tilemap.tilesets.map((tile) => tile.name),
        0,
        0,
      );

      if (layer) {
        layers.push(layer);
      }
    }

    this.createBoxes(layers);
    const { player, npc, monsters } = this.createCharacters(this.tilemap);

    const npcList = Object.values(npc).map((char) => {
      const config: CharacterDataHeadless = {
        id: char.config.sprite,
        //@ts-ignore
        sprite: char.sprite,
        walkingAnimationMapping: 4,
        startPosition: { x: 29, y: 40 },
        speed: 5,
      };

      return config;
    });

    const monsterList = Object.values(monsters).map((char) => {
      const config: CharacterDataHeadless = {
        id: char.config.id,
        //@ts-ignore
        sprite: char.sprite,
        walkingAnimationMapping: 0,
        startPosition: { x: 25, y: 38 },
        speed: 5,
      };

      return config;
    });

    const gridEngineConfig: GridEngineConfigHeadless = {
      characters: [
        {
          id: player.config.id,
          //@ts-ignore
          sprite: player.sprite,
          walkingAnimationMapping: 6,
          startPosition: playerConfig.startedPosition,
          speed: playerManager.getSkillValue("move"),
        },

        ...npcList,
        ...monsterList,
      ],
    };

    this.gridEngine.create(
      this.tilemap as unknown as Tilemap,
      gridEngineConfig,
    );

    // CREATE LISTENER TO CHANGE SPEED CONFIG

    this.cursors = this.input.keyboard?.createCursorKeys();
    const pointer = new Pointer(this);

    player.sprite.alpha = 0;

    const lightState: Record<string, Light> = {};
    const lights = (this.sceneConfig.lights || []).map(
      ({ x, y, color, intensity, radius, id, positionType }) => {
        const light = new Light(this, {
          x,
          y,
          color,
          intensity,
          radius,
          id,
          positionType,
        });
        if (id) lightState[id] = light;

        return light;
      },
    );
    this.lightElements = {
      list: lights,
      state: lightState,
    };

    const flames = (this.sceneConfig.flames || []).map((config) => {
      const flame = new Flame(this, config);

      return flame;
    });

    this.lights.enable().setAmbientColor(0x003b53); // dark color
    playerManager.listenChangeValue("move", (value) => {
      this.gridEngine.setSpeed(player.config.sprite, value);
    });

    this.tilemap?.layers.forEach((layer) =>
      layer.tilemapLayer.setPipeline("Light2D"),
    );
    player.sprite.setPipeline("Light2D");

    const ray = new Raycaster(this);
  }

  update(time: number, delta: number) {
    this.characters.player?.checkMovement();
  }
}
